// src/utils/format.ts
function formatDollars(cents) {
  const figure = (cents / 100).toLocaleString("en-US", {
    minimumFractionDigits: cents % 100 === 0 ? 0 : 2,
    maximumFractionDigits: 2
  });
  return `$${figure}`;
}

